// Display-only preview of an amount in Indian words (lakh / crore). The text the legacy app stores on a
// saved document is generated by the backend (backend/app/utils/amount_in_words.py); this is just the
// live hint shown while typing, so the counter can read the amount back to the devotee.
const ONES = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']
const TENS = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']

function below100(n) {
  return n < 20 ? ONES[n] : `${TENS[Math.floor(n / 10)]}${n % 10 ? ` ${ONES[n % 10]}` : ''}`
}
function below1000(n) {
  const h = Math.floor(n / 100)
  const r = n % 100
  return [h ? `${ONES[h]} Hundred` : '', r ? below100(r) : ''].filter(Boolean).join(' ')
}
function wholeInWords(n) {
  if (n === 0) return 'Zero'
  const parts = []
  const crore = Math.floor(n / 10000000)
  const lakh = Math.floor((n % 10000000) / 100000)
  const thousand = Math.floor((n % 100000) / 1000)
  const rest = n % 1000
  if (crore) parts.push(`${wholeInWords(crore)} Crore`)
  if (lakh) parts.push(`${below100(lakh)} Lakh`)
  if (thousand) parts.push(`${below100(thousand)} Thousand`)
  if (rest) parts.push(below1000(rest))
  return parts.join(' ')
}

export default function amountInWords(value) {
  const n = Number(value)
  if (!Number.isFinite(n) || n <= 0) return ''
  const rupees = Math.floor(n)
  const paise = Math.round((n - rupees) * 100)
  const r = rupees > 0 ? `Rupees ${wholeInWords(rupees)}` : ''
  const p = paise > 0 ? `${paise > 0 && rupees > 0 ? ' and ' : ''}${below100(paise)} Paise` : ''
  return `${r}${p} Only`
}
